const dados = $json.dados || {};
const convs = Array.isArray(dados.conversas) ? dados.conversas : [];
const LIMITE_PACIENTES = 40;
const LIMITE_TRANSCRICAO = 6000;
const LIMITE_TOTAL = 100000;
let corpo = 'Conversas do WhatsApp da clínica em ' + (dados.data_referencia || 'data não informada') + ' (' + convs.length + ' pacientes):\n\n';
let usados = 0;
for (const [i, c] of convs.slice(0, LIMITE_PACIENTES).entries()) {
  const primeiroNome = String(c.nome || 'não informado').trim().split(/\s+/)[0];
  const transcript = String(c.transcript || '[sem transcript]').slice(-LIMITE_TRANSCRICAO);
  const bloco = '=== PACIENTE ' + (i + 1) + ' (' + primeiroNome + ') — temperatura: ' + c.temperatura + ' · funil: ' + c.funil + ' · agendamento: ' + c.agendamento + (c.escalado ? ' · ESCALADO' : '') + (c.opt_out ? ' · OPT-OUT' : '') + '\n' + transcript + '\n\n';
  if (corpo.length + bloco.length > LIMITE_TOTAL) break;
  corpo += bloco;
  usados++;
}
if (usados < convs.length) corpo += '[Observação interna: ' + (convs.length - usados) + ' conversa(s) omitida(s) pelo limite de contexto.]\n';
const anterior = $json.auditoria_anterior;
if (anterior) corpo += '\n--- AUDITORIA ANTERIOR ---\n' + String(anterior).slice(0, 3000);
const system = 'Você é auditor sênior de atendimento e vendas por WhatsApp de uma clínica de medicina diagnóstica. Audite: humanização e rapport; método Vende-C; precisão de preços, exames e horários; compliance CFM e LGPD; conversão; oportunidades perdidas; e atuação humana. A clínica não agenda pelo bot e não realiza densitometria, ressonância, mamografia, colonoscopia/endoscopia ou eletroneuromiografia. Não exponha telefones nem outros identificadores. Responda em português para WhatsApp, máximo 40 linhas: nota geral e notas por critério; 2-3 destaques positivos; 2-3 pontos de atenção com exemplo curto; e 3 melhorias acionáveis. Se houver auditoria anterior, comece comparando a evolução e pendências. Seja específico, honesto e não invente fatos.';
const body = { model: 'gpt-5.6-luna', instructions: system,
  input: [{ role: 'user', content: corpo }], reasoning: { effort: 'low' },
  max_output_tokens: 2200, store: false };
return [{ json: { openai_body: body, pacientes_total: convs.length, pacientes_analisados: usados } }];

const texto = ($json.output || []).flatMap(o => o.content || [])
  .filter(c => c.type === 'output_text').map(c => c.text).join('\n').trim();
const t = texto || 'Falha ao gerar análise.';
return [{ json: { texto: '🔍 *ANA — Auditoria de Atendimento*\n\n' + t } }];

const texto = $input.first().json.texto;
const numeros = ['5512996010017','5512997743535','551238873535'];
return numeros.map(n => ({json: {number: n, texto}}));
